// Extract campaign data and create variables for this iteration
const campaign = $input.item.json;
const globalVars = $('Set Global Variables').item.json;

return {
  json: {
    campaign_id: campaign.id,
    campaign_name: campaign.name,
    campaign_status: campaign.status,
    start_date: globalVars.start_date,
    end_date: globalVars.end_date,
    sequence: campaign.sequences?.[0] || null,
    has_sequences: Boolean(campaign.sequences && campaign.sequences.length > 0)
  }
};

// Combine analytics data with campaign info and sequence data
const analyticsResponse = $input.item.json;
const campaignData = $('Prepare Campaign Data').item.json;
const analyticsArray = analyticsResponse.data || [];

// If no analytics data, return empty array
if (analyticsArray.length === 0) {
  return [];
}

// Process each analytics item
const results = analyticsArray.map(analytics => {
  const stepIndex = parseInt(analytics.step);
  const variantIndex = parseInt(analytics.variant);

  // Get sequence data
  let subject = '';
  let body = '';

  if (campaignData.sequence && campaignData.sequence.steps) {
    const step = campaignData.sequence.steps[stepIndex];
    if (step && step.variants) {
      const variant = step.variants[variantIndex];
      if (variant) {
        subject = variant.subject || '';
        body = variant.body || '';
      }
    }
  }

  // Convert HTML to plain text
  const plainTextBody = body
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<div[^>]*>/gi, '')
    .replace(/<\/div>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();

  return {
    date: campaignData.end_date,
    campaign_name: campaignData.campaign_name,
    campaign_id: campaignData.campaign_id,
    campaign_status: campaignData.campaign_status,
    step: analytics.step,
    variant: analytics.variant,
    sent: analytics.sent || 0,
    opened: analytics.opened || 0,
    unique_opened: analytics.unique_opened || 0,
    replies: analytics.replies || 0,
    unique_replies: analytics.unique_replies || 0,
    clicks: analytics.clicks || 0,
    unique_clicks: analytics.unique_clicks || 0,
    subject: subject,
    body: plainTextBody,
    reply_rate: analytics.sent > 0 ? ((analytics.unique_replies / analytics.sent) * 100).toFixed(2) + '%' : '0%',
    open_rate: analytics.sent > 0 ? ((analytics.unique_opened / analytics.sent) * 100).toFixed(2) + '%' : '0%'
  };
});

return results.map(item => ({ json: item }));

